const item=(action,label)=>({action,label});
const group=(label,children)=>({label,children});
export function contextEntries({image=false,many=false,selected=true}={}){const entries=[];if(image&&!many)entries.push(item('action:replace-image','Trocar imagem'),item('studio:crop','Recortar e enquadrar'),item('studio:fit-image-contain','Mostrar imagem inteira'),item('studio:fit-image-cover','Preencher moldura'),group('Máscara',['rectangle','circle','ellipse','shield','diamond','arch'].map(k=>item('studio:mask-'+k,({rectangle:'Retangular',circle:'Circular',ellipse:'Elíptica',shield:'Escudo',diamond:'Losango',arch:'Arco'})[k]))),group('Virar',[item('studio:flip-x','Horizontalmente'),item('studio:flip-y','Verticalmente')]),item('reset-image','Restaurar ajustes'));else if(selected&&!many)entries.push(item('studio:edit-content','Editar conteúdo'),group('Texto',[item('studio:edit-font','Fonte'),item('studio:edit-size','Tamanho'),item('studio:edit-align','Alinhamento'),item('studio:edit-color','Cor')]));if(selected)entries.push(item('copy','Copiar'),item('action:duplicate-block','Duplicar'));entries.push(item('paste','Colar'));if(selected){entries.push(group('Estilo',[item('studio:copy-appearance','Copiar estilo'),item('studio:paste-appearance','Colar estilo')]));const organize=[item('action:front','Trazer à frente'),item('action:back','Enviar para trás'),item('lock-group','Bloquear'),item('hide-group','Ocultar')];if(many)organize.unshift(item('action:group-selection','Agrupar'),item('action:ungroup-selection','Desagrupar'));entries.push(group('Organizar',organize));const align=many?['left','hcenter','right','top','vcenter','bottom'].map(k=>item('align:'+k,({left:'Esquerda',hcenter:'Centro horizontal',right:'Direita',top:'Topo',vcenter:'Centro vertical',bottom:'Base'})[k])):[item('page:left','Esquerda da página'),item('page:center','Centro da página'),item('page:right','Direita da página')];if(many)align.push(item('distribute:x','Distribuir horizontalmente'),item('distribute:y','Distribuir verticalmente'),item('equal-w','Igualar larguras'),item('equal-h','Igualar alturas'),item('equal-size','Igualar tamanhos'));entries.push(group('Alinhar',align),item('action:delete-block','Excluir'));}return entries;}
export function installContextMenu(E,command){let root=null;const close=()=>{root?.remove();root=null;},visibleButtons=menu=>[...menu.children].map(n=>n.querySelector(':scope > button')).filter(Boolean);
 function closeChildren(menu){for(const row of menu.children){const sub=row.querySelector(':scope > [role="menu"]');if(sub){sub.hidden=true;row.querySelector('button').setAttribute('aria-expanded','false');closeChildren(sub);}}}
 function place(menu,x,y){menu.style.left='0px';menu.style.top='0px';menu.hidden=false;const r=menu.getBoundingClientRect();menu.style.left=Math.max(8,Math.min(x,innerWidth-r.width-8))+'px';menu.style.top=Math.max(8,Math.min(y,innerHeight-r.height-8))+'px';}
 function openSub(button,sub,focus=false){const parent=button.closest('[role="menu"]');closeChildren(parent);const r=button.getBoundingClientRect();sub.hidden=false;const w=sub.getBoundingClientRect().width;place(sub,r.right+w+8>innerWidth?r.left-w+2:r.right-2,r.top-5);button.setAttribute('aria-expanded','true');if(focus)visibleButtons(sub)[0]?.focus({preventScroll:true});}
 function build(entries,parentButton=null){const menu=document.createElement('div');menu.className=parentButton?'context-submenu':'context-menu';menu.setAttribute('role','menu');if(parentButton){menu.hidden=true;menu.setAttribute('aria-label',parentButton.textContent);}for(const entry of entries){const row=document.createElement('div'),button=document.createElement('button');button.type='button';button.setAttribute('role','menuitem');button.textContent=entry.label;row.append(button);menu.append(row);if(entry.children){button.setAttribute('aria-haspopup','menu');button.setAttribute('aria-expanded','false');button.dataset.submenu=entry.label;const arrow=document.createElement('span');arrow.textContent='▸';arrow.setAttribute('aria-hidden','true');button.append(arrow);const sub=build(entry.children,button);row.append(sub);button.onclick=e=>{e.stopPropagation();openSub(button,sub,true);};row.onpointerenter=()=>openSub(button,sub);}else{button.dataset.context=entry.action;row.onpointerenter=()=>closeChildren(menu);button.onclick=()=>{const [kind,value]=entry.action.split(':');close();if(kind==='studio')document.dispatchEvent(new CustomEvent('studio-command',{detail:value}));else if(kind==='action')E.action(value,{dataset:{}});else if(kind==='page')E.action('align',{dataset:{align:value}});else if(kind==='align')E.action('align-reference',{dataset:{kind:value}});else if(kind==='distribute')E.action('distribute',{dataset:{axis:value}});else command(entry.action);};}}
 menu.onkeydown=e=>{e.stopPropagation();const buttons=visibleButtons(menu),index=buttons.indexOf(document.activeElement);if(['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length]?.focus({preventScroll:true});}if(e.key==='ArrowRight'){const button=document.activeElement,sub=button?.parentElement?.querySelector(':scope > [role="menu"]');if(sub){e.preventDefault();openSub(button,sub,true);}}if((e.key==='ArrowLeft'||e.key==='Escape')&&parentButton){e.preventDefault();menu.hidden=true;parentButton.setAttribute('aria-expanded','false');parentButton.focus({preventScroll:true});}else if(e.key==='Escape'){e.preventDefault();close();}};return menu;}
 document.addEventListener('pointerdown',e=>{if(root&&!root.contains(e.target))close();},true);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&root&&!root.contains(e.target))close();});document.querySelector('#sheet').addEventListener('contextmenu',e=>{if(E.mode!=='edit')return;e.preventDefault();const id=e.target.closest('[data-block]')?.dataset.block;if(id&&!E.selection.has(id))E.select(id,false,false,true);close();const b=E.getBlock();root=build(contextEntries({image:['image','portrait'].includes(b?.type),many:E.selection.size>1,selected:!!b}));document.body.append(root);place(root,e.clientX,e.clientY);visibleButtons(root)[0]?.focus({preventScroll:true});});return {close};}
